    sq: 'Domeni i dërguesit nuk është aktivizuar ende. Pa të, e-maili do të përfundonte te mysafiri në dosjen e spam-it, pa e vënë re askush.',
    el: 'Ο τομέας αποστολέα δεν έχει ενεργοποιηθεί ακόμη. Χωρίς αυτόν το email θα κατέληγε στα ανεπιθύμητα του επισκέπτη χωρίς να το αντιληφθεί κανείς.',
    lt: 'Siuntėjo domenas dar neaktyvuotas. Be jo laiškas atsidurtų svečio šlamšto aplanke, ir niekas to nepastebėtų.',
