    hu: 'Ennek a vendégnek',
    ro: 'Către acest oaspete',
    bg: 'На този гост',
    hr: 'Ovom gostu',
    sr: 'Ovom gostu',
    mk: 'На овој гостин',
    sq: 'Te ky mysafir',
    el: 'Σε αυτόν τον επισκέπτη',
